-- composition of rule kernels CoverIdxScan x ExistsToJoin (sqlite), template not_exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, CAST('abc' AS TEXT) AS c1 FROM t0 AS a1 UNION ALL SELECT FALSE AS c0, CAST('NaN' AS TEXT) AS c1) AS ka WHERE NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 20) SELECT CAST('c4ca4238a0b923820dcc509a6f75849b' AS TEXT) AS c0, CAST('{"k": 1}' AS TEXT) AS c1 FROM rc AS a1 WHERE (EXISTS (SELECT CAST(5e-324 AS REAL) AS c0, '{"k": 2, "a": [0]}' AS c1 FROM tp AS a2))) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 20) SELECT CAST('c4ca4238a0b923820dcc509a6f75849b' AS TEXT) AS c0, CAST('{"k": 1}' AS TEXT) AS c1 FROM rc AS a1 WHERE (EXISTS (SELECT CAST(5e-324 AS REAL) AS c0, '{"k": 2, "a": [0]}' AS c1 FROM tp AS a2))) AS kb) = 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, CAST('abc' AS TEXT) AS c1 FROM t0 AS a1 UNION ALL SELECT FALSE AS c0, CAST('NaN' AS TEXT) AS c1) AS ka) ELSE 0 END
